-- Optional: the app creates this automatically (createDatabaseIfNotExist=true),
-- but you can also run it yourself in MySQL Workbench / the mysql client.
-- Tables (users, products, cart_items, orders, order_items, contact_messages)
-- are generated by Hibernate on first start (spring.jpa.hibernate.ddl-auto=update).
CREATE DATABASE IF NOT EXISTS thinkmart CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
